/// Select explicitly maintained indexes from the canonical schema, in caller order.
/// Missing or repeated names fail closed rather than silently changing maintenance.
pub(crate) fn selected_index_statements(sql: &str, names: &[&str]) -> Option<String> {
    let statements = split_sql_statements(sql);
    let mut result = String::new();
    for (position, name) in names.iter().enumerate() {
        if names[..position].contains(name) {
            return None;
        }
        let mut matching = statements.iter().copied().filter(|stmt| {
            matches!(
                classify_statement(stmt),
                StmtKind::CreateIndex | StmtKind::CreateUniqueIndex
            ) && index_name(stmt) == Some(*name)
        });
        let statement = matching.next()?;
        if matching.next().is_some() {
            return None;
        }
        result.push_str(statement);
        result.push_str(";\n");
    }
    Some(result)
}

/// Only immutable compiled SQL is cached, never a database state or read epoch.
/// Normal writable opens keep executing the original two statements in order.
fn physical_index_maintenance_sql() -> CcResult<&'static str> {
    static SQL: OnceLock<Option<String>> = OnceLock::new();
    SQL.get_or_init(|| {
        crate::direct_writer::selected_index_statements(
            FULL_SCHEMA_SQL,
            &[
                "semantic_outbox_fifo_pending",
                "chunk_symbol_identity_doc_key",
            ],
        )
    })
    .as_deref()
    .ok_or_else(|| {
        CcError::Database(
            "canonical physical index maintenance requires one definition per index".into(),
        )
    })
}

